      // Recessed VU meters: typography and calibration are painted into compact canvas textures.
      function meterTexture(label){const c=document.createElement('canvas');c.width=256;c.height=128;const x=c.getContext('2d');x.fillStyle='#101c33';x.fillRect(0,0,256,128);x.strokeStyle='#a9bddf';x.lineWidth=2;x.strokeRect(5,5,246,118);x.fillStyle='#d9e2f2';x.font='bold 16px Arial';x.fillText(label,16,25);x.strokeStyle='#d5dfef';x.lineWidth=3;x.beginPath();x.arc(128,128,75,Math.PI,Math.PI*2);x.stroke();for(let i=0;i<=10;i++){const a=Math.PI+i*Math.PI/10,inner=59,outer=72;x.beginPath();x.moveTo(128+Math.cos(a)*inner,128+Math.sin(a)*inner);x.lineTo(128+Math.cos(a)*outer,128+Math.sin(a)*outer);x.strokeStyle=i>7?'#df8b73':'#bdcdeb';x.lineWidth=i%5===0?2:1;x.stroke()}x.fillStyle='#aebddd';x.font='11px Arial';x.fillText('−20',19,111);x.fillText('0',121,61);x.fillText('+3',215,111);const tex=new T.CanvasTexture(c);tex.encoding=T.sRGBEncoding;return tex}
